BEGIN;

SET LOCAL standard_conforming_strings = on;

INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷84·晋少帝本纪·开运三年四月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/bd391620db0dcdfa704b6c166979a0422e9213ef/content/books/zizhi-tongjian/vol-285/year-0946/part-01/sources/library/jiuwudaishi-084-946-april/source.txt", "note": "《旧五代史》卷84·晋少帝本纪·开运三年四月，段落 jiu-wudaishi-205deb4a7860-p002037；已核上下文，底本原字保留，纸本及异文待核。", "id": "40d755c0-9a8f-5e9f-aaf1-466d6d1ee4e1"}, {"title": "旧五代史·卷84·晋少帝本纪·开运三年二月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/bd391620db0dcdfa704b6c166979a0422e9213ef/content/books/zizhi-tongjian/vol-285/year-0946/part-01/sources/library/jiuwudaishi-084-946-february/source.txt", "note": "《旧五代史》卷84·晋少帝本纪·开运三年二月，段落 jiu-wudaishi-205deb4a7860-p002035；已核上下文，底本原字保留，纸本及异文待核。", "id": "72ac2ee0-8b9b-5c66-be43-25d0829d3a77"}, {"title": "旧五代史·卷84·晋少帝本纪·开运三年六月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/bd391620db0dcdfa704b6c166979a0422e9213ef/content/books/zizhi-tongjian/vol-285/year-0946/part-01/sources/library/jiuwudaishi-084-946-june/source.txt", "note": "《旧五代史》卷84·晋少帝本纪·开运三年六月，段落 jiu-wudaishi-205deb4a7860-p002039；已核上下文，底本原字保留，纸本及异文待核。", "id": "4617db20-6eb1-5299-a22f-337380b5333b"}, {"title": "宋史·卷253·孙行友传", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/bd391620db0dcdfa704b6c166979a0422e9213ef/content/books/zizhi-tongjian/vol-285/year-0946/part-01/sources/library/songshi-253-sun-xingyou/source.txt", "note": "《宋史》卷253·孙行友传，段落 songshi-9c6e46fee832-p057425；已核上下文，底本原字保留，纸本及异文待核。", "id": "31ed85da-feb1-562f-979e-f49d8e40b652"}, {"title": "资治通鉴·卷285·开运三年·二月至六月及追述", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/bd391620db0dcdfa704b6c166979a0422e9213ef/content/books/zizhi-tongjian/vol-285/year-0946/part-01/sources/library/tongjian-285-946-february-june/source.txt", "note": "《资治通鉴》卷285·开运三年·二月至六月及追述，段落 zizhi-tongjian-a63549944a71-p003385；已核上下文，底本原字保留，纸本及异文待核。", "id": "12262346-c363-5eab-b988-7a959b47885a"}, {"title": "资治通鉴·卷285·后晋纪六·开运二年十一月至十二月及后续", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/7fdbc991f6904ba3ca54b43df9788457ad6b8e5f/content/books/zizhi-tongjian/vol-285/year-0945/part-02/sources/library/tongjian-285-945-november-december/source.txt", "note": "《资治通鉴》卷285·后晋纪六·开运二年十一月至十二月及后续，段落 zizhi-tongjian-a63549944a71-p003384；已核卷号传主，电子本及异文待纸本校核。", "id": "7f3abe80-c419-5cfb-87b7-588ae233b38c"}, {"title": "新五代史·卷62·南唐世家·冯延巳等", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/0bf9f2cc5934c50fb020b79750ac51ac7d48f541/content/books/zizhi-tongjian/vol-283/year-0943/part-01/sources/library/xinwudaishi-062-feng-name/source.txt", "note": "《新五代史》卷62·南唐世家·冯延巳等，段落 xin-wudaishi-b08f244b9241-p003139；已核上下文及传主，纸本及异文待核。", "id": "819d41cd-204a-5095-8cdb-49e78419f252"}, {"title": "新五代史·卷68·闽世家·王氏灭亡纪年说明", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/e77e2ab2ec0aa76443441349e3b3533923c10437/content/books/zizhi-tongjian/vol-285/year-0945/part-01/sources/library/xinwudaishi-068-fall-year/source.txt", "note": "《新五代史》卷68·闽世家·王氏灭亡纪年说明，段落 xin-wudaishi-b08f244b9241-p003415；已核卷号与传主，电子本及异文待纸本校核。", "id": "af3458df-4cef-5654-8b54-5a0ab901bec3"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "宋齐丘", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化二年条所见人物：宋齐丘。", "biography": null, "status": "draft", "id": "313ec6c3-7027-5fef-8b5d-b79d259f9c8a"}, {"name": "李建勋", "aliases": ["李建勳"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：李建勋，节度副使、屡陈功业者。", "biography": null, "status": "draft", "id": "6b23676b-32be-5201-8ad3-171b7cc648e3"}, {"name": "冯延巳", "aliases": ["馮延巳", "冯延己", "馮延己", "冯延已"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐官员，曾任驾部郎中、齐王元帅府常书记。《资治通鉴》本段作冯延己及延已，《新五代史》作冯延巳；据同一南唐政局、陈觉及常梦锡等对应关系校核为同人，展示采用冯延巳，原文异体保留。生卒年尚未核。", "biography": null, "status": "draft", "id": "0b3ed4d7-1a4c-50a5-ad65-aee4b82089ba"}, {"name": "高越", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐水部郎中。946年正月条下记他上书指出冯延巳兄弟的过恶，李璟发怒，将他贬为蕲州司士。生卒、籍贯未载。", "biography": null, "status": "draft", "id": "8e8eb122-1eff-54ef-b1ce-6aab3faade16"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "常梦锡", "aliases": ["常夢錫"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐官员，万年人。941年四月与陈觉一起被李昪任命为宣徽副使。生卒年未据本段确定。", "biography": null, "status": "draft", "id": "9eaabd48-0b3a-5cc3-a5ec-f9107c987328"}, {"name": "严续", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷270贞明四年条所见人物：严续。", "biography": null, "status": "draft", "id": "57b5cb9f-cb31-5e6a-87de-6363e1836468"}, {"name": "严可求", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷265天祐二年条所见人物：严可求。", "biography": null, "status": "draft", "id": "9f00697c-667c-53de-bf1a-d30608eb0cb4"}, {"name": "赵在礼", "aliases": ["趙在禮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷274同光四年条所见人物：赵在礼。", "biography": null, "status": "draft", "id": "90ff68a5-70f2-5182-8802-93859bae2990"}, {"name": "石重贵", "aliases": ["石重貴"], "era": "五代十国", "birth_year": 914, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：石重贵，被叙侄子及养子身份者。", "biography": null, "status": "draft", "id": "2741e60a-9bf9-56a7-b30d-3db439caa139"}, {"name": "石延煦", "aliases": ["延煦"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "石敬瑭的孙子，石重贵养子，石延宝的兄长。946年任镇宁节度使，与赵在礼的女儿成婚；《资治通鉴》记三月庚申，《旧五代史》记四月，婚事纪月不同，分别保留。亲生父母姓名及生卒年未载。", "biography": null, "status": "draft", "id": "ed348273-f4e9-5b33-9080-aa449de66dcc"}, {"name": "石延宝", "aliases": ["石延寶", "延宝", "延寶"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "石敬瑭的孙子，石重贵养子，石延煦的弟弟。946年记石延煦婚事时，史书补叙二人为石重贵养子。亲生父母姓名与收养年月、生卒年未载。", "biography": null, "status": "draft", "id": "79b31372-7a96-5605-a27f-799f2f8a9daf"}, {"name": "石敬瑭", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：石敬瑭。", "biography": null, "status": "draft", "id": "bf42d98c-7477-5be1-a767-867fe26cf617"}, {"name": "王继勋", "aliases": ["王繼勳"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "王延政的从子，王氏宗族成员。944年留从效杀黄绍颇后请他主持泉州军府，王延政随后任他为侍中、泉州刺史。具体亲生父姓名本段未载。", "biography": null, "status": "draft", "id": "3ecb3355-a3dd-5a2f-a0b9-12d6af9a06ab"}, {"name": "李仁达", "aliases": ["李仁達"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "光州人，曾任闽元从指挥使，多次在建州、福州之间投奔不同执政者。945年与陈继珣、黄仁讽发动福州政变，杀王继昌和吴成义，拥立僧卓岩明。后来又杀黄仁讽、陈继珣，将福州兵权集中到自己手中。生卒年本次引文未载。", "biography": null, "status": "draft", "id": "97ca7dea-54b1-5a38-a747-3dc803037d55"}, {"name": "李弘通", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李仁达的弟弟。946年四月，李仁达派他领兵攻泉州；留从效废王继勋后率军击败他。生卒年未载。", "biography": null, "status": "draft", "id": "b6f8a903-5e05-58c9-87a8-384906afa3f9"}, {"name": "冯晖", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷263天复二年条所见人物：冯晖。", "biography": null, "status": "draft", "id": "e59e2b00-2873-5968-ab4c-938628164ecf"}, {"name": "拓跋彦超", "aliases": ["拓跋彥超"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "党项首领。939年冯晖接任朔方节度使后，拓跋彦超前往祝贺，受到优待并被留在城中。生卒年未载。", "biography": null, "status": "draft", "id": "07cc4da4-56f5-51e9-b06f-b2b7fe597419"}, {"name": "王令温", "aliases": ["王令溫"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "瀛州河间人，后晋永清军节度使。免除邵珂军职，入朝时将其子邵崇范带在身边作人质。贝州陷落后家属被契丹俘获，944年正月被调为邓州节度使。生卒年本批未录。", "biography": null, "status": "draft", "id": "86d0426b-7115-5ca5-8f2c-358de92831a5"}, {"name": "石存", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "946年《资治通鉴》记石存一族与拓跋彦超、也厮褒两族共同攻灵州。名字、所属部众与此役相联系，具体官号及生卒年未载。", "biography": null, "status": "draft", "id": "bb41d3f4-5f49-5db4-b940-309cb7ac566b"}, {"name": "也厮褒", "aliases": ["也廝褒"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "946年《资治通鉴》记也厮褒一族与拓跋彦超、石存两族共同攻灵州。具体官号及生卒年未载。", "biography": null, "status": "draft", "id": "7db23ea8-6ff6-5129-ba6b-5548cbbe55e0"}, {"name": "王令周", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "朔方节度使王令温的弟弟。拓跋彦超、石存、也厮褒三族攻灵州时被杀，王令温随后在946年四月戊午上表告急；死亡具体日未载。", "biography": null, "status": "draft", "id": "40a6534d-bbc3-5404-941d-8fcfe3c62215"}, {"name": "留从效", "aliases": ["留從效", "留從効"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "泉州散员指挥使，主书称桃林人，《宋史》记泉州永春人。944年参与杀黄绍颇、迎王继勋，并任都指挥使。新史写留從効，沿用同一主体。生卒年本次引文未载。", "biography": null, "status": "draft", "id": "55786b2f-a228-5281-a323-e9c521b2988f"}, {"name": "王继成", "aliases": ["王繼成"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "王延政的从子，王氏宗族成员。944年程谟杀漳州刺史后立他暂掌漳州。亲生父姓名本段未载。", "biography": null, "status": "draft", "id": "4f09de43-cd4b-56a5-a731-b286597a2338"}, {"name": "许文稹", "aliases": ["許文稹", "许文缜", "許文縝"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "同安人，汀州刺史。944年朱文进掌权后率郡投降朱文进。《新五代史》对应汀州守将作許文縝，保留姓名字形异文；该书后文投降王延政为另一阶段，不混为当前投降对象。生卒年未载。", "biography": null, "status": "draft", "id": "6717f767-1ab2-52b8-8015-c778cc06ee45"}, {"name": "孙深意", "aliases": ["孫深意"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "居狼山佛舍的尼姑。史书记她以术聚众，孙方简、孙行友自称是她的侄子并侍奉她；她去世后，孙方简继续其术，称她坐化。史书的灵验说法不视作已经验证的超自然事实；死亡年月未载。", "biography": null, "status": "draft", "id": "9bb24292-7cfb-525b-b996-152b2ad1a5ee"}, {"name": "孙方简", "aliases": ["孫方簡", "孙方谏", "孫方諫"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》称中山人，聚众于狼山，归附后晋后任东北招收指挥使，后来转投契丹并拘执刘延翰。《宋史》孙行友传写作孙方谏，记他是孙行友的兄子；《资治通鉴》记孙行友是其弟，亲属记载冲突待核。姓名字形与主体按狼山、职衔和事迹对应复用，生卒年未核。", "biography": null, "status": "draft", "id": "17e0109c-1d9d-5437-a7d0-5c7be7b6beb8"}, {"name": "孙行友", "aliases": ["孫行友"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "与孙方简聚众于狼山，借孙深意的术及边民避乱扩展部众。《宋史》记为莫州清苑人，出身务农，后任孙方谏的副手；《资治通鉴》记为孙方简之弟，《宋史》却记孙方谏为他的兄子，亲属与籍贯表述分别保留待核。生卒年未核。", "biography": null, "status": "draft", "id": "297fda14-1470-5546-b76b-7b2461eb1d3d"}, {"name": "杜重威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "朔州人，后晋将领，妻子是石敬瑭的妹妹乐平长公主。937年以护圣都指挥使身份率军驻卫州。", "biography": null, "status": "draft", "id": "e5e23c10-447f-5238-bc56-f376300f9bac"}, {"name": "刘延翰", "aliases": ["劉延翰"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "天雄节度使杜重威的元随军将。946年奉命到边地买马，被孙方简拘执送给契丹；逃归后，六月壬戌抵大梁，报告孙方简拟引契丹入侵并请求备御。生卒、籍贯未载。", "biography": null, "status": "draft", "id": "d7c36228-200f-53df-b1c4-75e54b37f634"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
